//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::nat::div_exact, nat::mul, nat::rem`; the
//! native twin is `benches/native/Bench/NatDivExact.lean`.
//! Nat words on both sides (2n+1); every result stays below 2^63; both sides make the program's
//! test that supplies the proof (`b ∣ a`, a remainder)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::nat;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let b = nat_box((x >> 4) & 0xFF);
            let a = nat_res(nat::mul(nat_arg(nat_box(x >> 34)), nat_arg(b)));
            if nat::rem(nat_arg(a), nat_arg(b)).is_zero() {
                nat_unbox(nat_res(nat::div_exact(nat_arg(a), nat_arg(b))))
            } else {
                0
            }
        });
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
